def analyze_sentiment(lyrics: str) -> dict:
    positive_words = {'beautiful', 'love', 'happy', 'joy', 'smile', 'bright', 'peace', 'hope'}
    negative_words = {'sorrow', 'fear', 'hate', 'sad', 'cry', 'dark', 'pain', 'anger'}

    words = lyrics.lower().split()
    counts = {'positive': 0, 'negative': 0, 'neutral': 0}

    for word in words:
        if word in positive_words:
            counts['positive'] += 1
        elif word in negative_words:
            counts['negative'] += 1
        else:
            counts['neutral'] += 1

    return counts
```

